import{_ as a,c as e,o as r,a1 as t,en as l,eo as i,ep as n,eq as s,er as o,es as d,et as p}from"./chunks/framework.CkSEW8EO.js";const x=JSON.parse('{"title":"VS Code tillägg","description":"","frontmatter":{"outline":[1,6]},"headers":[],"relativePath":"web1/2-tools/extensions.md","filePath":"web1/2-tools/extensions.md"}'),g={name:"web1/2-tools/extensions.md"},k=t('<h1 id="vs-code-tillagg" tabindex="-1">VS Code tillägg <a class="header-anchor" href="#vs-code-tillagg" aria-label="Permalink to &quot;VS Code tillägg&quot;">​</a></h1><p>Tillägg (engelska: extensions) är små program eller plugins som kan installeras i VS Code för att utöka dess funktionalitet. Dessa kan exempelvis hjälpa till med syntaxmarkering, kodkomplettering, felsökning, eller andra verktyg som underlättar programmering.</p><p align="center"><img src="'+l+'" alt="Tilläg bild"></p><h2 id="rekommenderade-tillagg-for-webbutveckling-1" tabindex="-1">Rekommenderade tillägg för Webbutveckling 1 <a class="header-anchor" href="#rekommenderade-tillagg-for-webbutveckling-1" aria-label="Permalink to &quot;Rekommenderade tillägg för Webbutveckling 1&quot;">​</a></h2><p>För gymnasieelever som läser kursen Webbutveckling 1, där fokus vanligtvis ligger på HTML, CSS och JavaScript, är följande tillägg användbara:</p><h3 id="_1-html-och-css" tabindex="-1">1. HTML och CSS <a class="header-anchor" href="#_1-html-och-css" aria-label="Permalink to &quot;1. HTML och CSS&quot;">​</a></h3><p><span class="f">HTML CSS Support</span><br> Ger bättre stöd för autokomplettering av klasser och id:n i HTML baserat på CSS-filer.</p><p><img src="'+i+'" alt=""></p><p><span class="f">Live Server</span><br> Startar en lokal server och låter elever se sina ändringar i realtid i webbläsaren utan att behöva ladda om sidan manuellt.</p><p><img src="'+n+'" alt=""></p><p><span class="f">Prettier - Code Formatter</span><br> Hjälper till att automatiskt formatera koden enligt standardiserade regler, vilket gör koden mer läsbar.</p><p><img src="'+s+'" alt=""></p><br><h3 id="_2-design-och-stil" tabindex="-1">2. Design och stil <a class="header-anchor" href="#_2-design-och-stil" aria-label="Permalink to &quot;2. Design och stil&quot;">​</a></h3><p><span class="f">Color Highlight</span><br> Markerar färgkoder (t.ex. #ff0000 eller rgba(255,0,0,0.5)) med deras faktiska färger, vilket gör det lättare att arbeta med design.</p><p><span class="f">CSS Peek</span><br> Låter elever se definitioner av CSS-klasser direkt från HTML-filen.</p><br><h3 id="_3-allman-produktivitet" tabindex="-1">3 Allmän produktivitet <a class="header-anchor" href="#_3-allman-produktivitet" aria-label="Permalink to &quot;3 Allmän produktivitet&quot;">​</a></h3><p><span class="f">Auto Rename Tag</span><br> Synkroniserar automatiskt ändringar av öppnings- och sluttaggar i HTML.</p><p><img src="'+o+'" alt=""></p><p><span class="f">Rainbow Brackets 2</span><br> Färglägger matchande parenteser, vilket gör det enklare att hålla koll på kodblock</p><p><img src="'+d+'" alt=""></p><p><span class="f">Path Intellisense</span><br> Ger autokomplettering för filvägar, vilket är praktiskt när man länkar till bilder, CSS-filer eller JavaScript-filer.</p><br><h3 id="_4-extra-verktyg-for-nyborjare" tabindex="-1">4. Extra verktyg för nybörjare <a class="header-anchor" href="#_4-extra-verktyg-for-nyborjare" aria-label="Permalink to &quot;4. Extra verktyg för nybörjare&quot;">​</a></h3><p><span class="f">Code Spell Checker</span><br> Markerar stavfel i koden, vilket kan vara användbart för att undvika fel i variabelnamn eller kommentarer.</p><p><span class="f">Markdown All in One</span><br> Bra för att skapa dokumentation och README-filer i Markdown, vilket kan vara en del av projekt i kursen.</p><br><h3 id="_5-javascript" tabindex="-1">5. JavaScript <a class="header-anchor" href="#_5-javascript" aria-label="Permalink to &quot;5. JavaScript&quot;">​</a></h3><p><span class="f">JavaScript (ES6) code snippets</span><br> Ger användbara kodsnuttar och autokomplettering för moderna JavaScript-funktioner.</p><p><span class="f">ESLint</span><br> Identifierar och markerar vanliga fel i JavaScript-kod, samt föreslår förbättringar enligt moderna standarder.</p><br><h2 id="hur-installerar-man-ett-tillagg" tabindex="-1">Hur installerar man ett tillägg? <a class="header-anchor" href="#hur-installerar-man-ett-tillagg" aria-label="Permalink to &quot;Hur installerar man ett tillägg?&quot;">​</a></h2><ol><li>Öppna VS Code.</li><li>Klicka på <strong>Extensions-ikonen</strong> i <strong>sidofältet</strong> (ser ut som en fyrkant med en liten ruta bredvid, markerat med en röd fyrkant på bilden nedan).</li><li>Sök efter namnet på tillägget i <strong>sökfältet</strong>.</li><li>Klicka på <strong>Install</strong> för att lägga till tillägget.</li></ol><p><img src="'+p+'" alt=""></p><br><h2 id="varfor-ar-dessa-tillagg-bra-for-dig" tabindex="-1">Varför är dessa tillägg bra för dig? <a class="header-anchor" href="#varfor-ar-dessa-tillagg-bra-for-dig" aria-label="Permalink to &quot;Varför är dessa tillägg bra för dig?&quot;">​</a></h2><ul><li>De är enkla att använda och hjälper dig att snabbt se resultat av ditt arbete.</li><li>De förbättrar förståelsen för grundläggande webbtekniker som HTML, CSS och JavaScript.</li><li>Verktygen minskar frustrationen genom att automatisera vissa uppgifter och markera vanliga fel.</li></ul><p>Med dessa tillägg kan du fokusera mer på att lära dig grunderna i webbutveckling utan att fastna i tekniska detaljer.</p>',39),c=[k];function m(f,b,h,u,v,_){return r(),e("div",null,c)}const C=a(g,[["render",m]]);export{x as __pageData,C as default};
